 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            minr = min(y for y, x in comp)
            maxr = max(y for y, x in comp)
            minc = min(x for y, x in comp)
            maxc = max(x for y, x in comp)
            colors = {}
            for y, x in comp:
                depth = min(y-minr, maxr-y, x-minc, maxc-x)
                color = grid[y][x]
                colors[color] = min(colors.get(color, depth), depth)
            ordered = sorted(colors, key=lambda color: (colors[color], color))
            mapping = {color: ordered[len(ordered)-1-i] for i, color in enumerate(ordered)}
            for y, x in comp:
                out[y][x] = mapping[grid[y][x]]
    return out
